"""Tests for scripts/check_lock_hashes.py."""

from pathlib import Path

import pytest

from check_lock_hashes import check_text, main, requirement_names

HASH_A = "a" * 64
HASH_B = "b" * 64

GOOD_LOCK = f"""\
# This file is autogenerated by pip-compile
anyio==4.0.0 \\
    --hash=sha256:{HASH_A} \\
    --hash=sha256:{HASH_B}
    # via httpx
idna==3.6 \\
    --hash=sha256:{HASH_A}
    # via anyio
"""


def test_good_lock_passes() -> None:
    assert check_text(GOOD_LOCK) == (2, [])


def test_requirement_names_follow_file_order() -> None:
    assert requirement_names(GOOD_LOCK) == ["anyio", "idna"]


def test_package_without_a_hash_is_reported() -> None:
    text = f"anyio==4.0.0 \\\n    --hash=sha256:{HASH_A}\nidna==3.6\n"
    packages, problems = check_text(text)
    assert packages == 2
    assert problems == ["no sha256 hash: idna"]


def test_malformed_hash_is_reported() -> None:
    packages, problems = check_text("idna==3.6 \\\n    --hash=sha256:abc123\n")
    assert packages == 1
    assert problems == ["no sha256 hash: idna"]


def test_unpinned_requirement_is_reported() -> None:
    _, problems = check_text(f"flask>=2 \\\n    --hash=sha256:{HASH_A}\n")
    assert problems[0] == "not pinned with ==: flask>=2"


def test_empty_lock_is_reported() -> None:
    assert check_text("# nothing here\n") == (0, ["no packages found"])


def test_main_returns_zero_for_a_good_file(
    tmp_path: Path, capsys: pytest.CaptureFixture[str]
) -> None:
    lock = tmp_path / "requirements.txt"
    lock.write_text(GOOD_LOCK, encoding="utf-8")
    assert main([str(lock)]) == 0
    assert "2 packages" in capsys.readouterr().out


def test_main_returns_one_for_a_bad_or_missing_file(
    tmp_path: Path, capsys: pytest.CaptureFixture[str]
) -> None:
    bad = tmp_path / "bad.txt"
    bad.write_text("idna==3.6\n", encoding="utf-8")
    assert main([str(bad)]) == 1
    assert "no sha256 hash: idna" in capsys.readouterr().err
    assert main([str(tmp_path / "missing.txt")]) == 1
